package com.cob.emr.ddd.domain.medicalnote.model.valueobjects;public enum RehabPotentialRating {    EXCELLENT("Excellent"),    GOOD("Good"),    FAIR("Fair"),    POOR("Poor"),    GUARDED("Guarded");    private final String displayName;    RehabPotentialRating(String displayName) {        this.displayName = displayName;    }    public String getDisplayName() {        return displayName;    }    public static RehabPotentialRating fromString(String value) {        if (value == null) return null;        for (RehabPotentialRating rating : values()) {            if (rating.displayName.equalsIgnoreCase(value)) {                return rating;            }        }        return null;    }}
